-- Disposable fixtures only. Run as the project database administrator. Always rolls back.
begin;
create function pg_temp.assert_true(ok boolean,msg text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'TEST FAILED: %',msg;end if;end $$;
create temp table fixture(k text primary key,id uuid default gen_random_uuid());
insert into fixture(k) values('owner'),('manager'),('viewer'),('outsider'),('network'),('other_network'),('unit'),('second_unit'),('other_unit'),('sector'),('second_sector'),('role'),('person'),('assignment'),('second_assignment');
grant select on fixture to authenticated;
create function pg_temp.f(key text) returns uuid language sql as $$ select id from fixture where k=key $$;
insert into auth.users(id,email,email_confirmed_at,aud,role) select id,k||'-'||id::text||'@example.invalid',now(),'authenticated','authenticated' from fixture where k in('owner','manager','viewer','outsider');
insert into public.networks(id,name) values(pg_temp.f('network'),'Verification network'),(pg_temp.f('other_network'),'Unrelated verification network');
insert into public.units(id,network_id,name,code,settings) select f.id,case when f.k='other_unit' then pg_temp.f('other_network') else pg_temp.f('network') end,f.k,f.k,jsonb_set((select settings from public.units limit 1),'{policy}','{"weeklyHours":40,"dailyHours":8,"restHours":11,"maxWorkDays":5,"maxConsecutive":5}') from fixture f where k in('unit','second_unit','other_unit');
insert into public.memberships(user_id,network_id,unit_id,role) values(pg_temp.f('owner'),pg_temp.f('network'),null,'owner'),(pg_temp.f('manager'),pg_temp.f('network'),pg_temp.f('unit'),'manager'),(pg_temp.f('viewer'),pg_temp.f('network'),pg_temp.f('unit'),'viewer');
insert into public.sectors(id,unit_id,name) values(pg_temp.f('sector'),pg_temp.f('unit'),'Test sector'),(pg_temp.f('second_sector'),pg_temp.f('second_unit'),'Test sector');
insert into public.job_roles(id,network_id,name) values(pg_temp.f('role'),pg_temp.f('network'),'Test role');
insert into public.people(id,network_id,name,weekly_hours,contract_confirmed) values(pg_temp.f('person'),pg_temp.f('network'),'Test person',40,true);
insert into public.unit_assignments(id,unit_id,network_id,person_id,sector_id,role_id,starts_on) values(pg_temp.f('assignment'),pg_temp.f('unit'),pg_temp.f('network'),pg_temp.f('person'),pg_temp.f('sector'),pg_temp.f('role'),'2026-10-19'),(pg_temp.f('second_assignment'),pg_temp.f('second_unit'),pg_temp.f('network'),pg_temp.f('person'),pg_temp.f('second_sector'),pg_temp.f('role'),'2026-10-19');
select set_config('request.jwt.claim.sub',pg_temp.f('owner')::text,true);
set local role authenticated;
select pg_temp.assert_true((select count(*)=1 from public.networks),'owner network isolation');
select pg_temp.assert_true((select count(*)=2 from public.units),'owner units isolation');
do $$ declare v int;s public.schedules;rows jsonb;issues jsonb;begin
 select revision into v from public.units where id=pg_temp.f('unit');
 perform public.mutate_configuration(pg_temp.f('unit'),v,'units',jsonb_build_object('id',pg_temp.f('unit'),'settings',jsonb_set((select settings from public.units where id=pg_temp.f('unit')),'{policy}','{"weeklyHours":42,"dailyHours":9,"restHours":11,"maxWorkDays":5,"maxConsecutive":5}')),false);
 select revision into v from public.units where id=pg_temp.f('unit');
 perform public.mutate_configuration(pg_temp.f('unit'),v,'people',jsonb_build_object('id',pg_temp.f('person'),'weekly_hours',40,'weekly_hours_source','unit','contract_confirmed',false),false);
 select jsonb_agg(jsonb_build_object('assignment_id',x.id,'person_id',x.person_id,'work_date',d::date,'kind',case when d::date<'2026-10-24' then 'work' else 'off' end,'sector_id',x.sector_id,'role_id',x.role_id,'start_time','07:00','end_time','16:24','break_start','11:00','break_end','12:00')) into rows from public.unit_assignments x cross join generate_series('2026-10-19'::timestamp,'2026-10-25'::timestamp,'1 day') d where x.unit_id=pg_temp.f('unit');
 select revision into v from public.units where id=pg_temp.f('unit');
 s=public.save_schedule(pg_temp.f('unit'),'2026-10-19',0,v,rows,'Weekly hours regression');
 issues=public.schedule_issues(s.id);
 perform pg_temp.assert_true(not exists(select 1 from jsonb_array_elements(issues) i where i->>'code'='weekly'),'provisional reference uses unit 42, despite stored seed 40');
 perform pg_temp.assert_true((select weekly_hours=40 from public.people where id=pg_temp.f('person')),'stored original hours preserved');
 select revision into v from public.units where id=pg_temp.f('unit');
 begin perform public.mutate_configuration(pg_temp.f('unit'),v,'people',jsonb_build_object('id',pg_temp.f('person'),'contract_confirmed',true),false);raise exception 'TEST FAILED inheritance confirmed as contract';exception when check_violation then null;end;
 perform public.mutate_configuration(pg_temp.f('unit'),v,'people',jsonb_build_object('id',pg_temp.f('person'),'weekly_hours_source','contract','contract_confirmed',true),false);
 perform pg_temp.assert_true(exists(select 1 from jsonb_array_elements(public.schedule_issues(s.id)) i where i->>'code'='weekly'),'confirmed 40-hour contract remains limited to 40');
 select revision into v from public.units where id=pg_temp.f('unit');
 perform public.save_employee(pg_temp.f('unit'),v,pg_temp.f('assignment'),jsonb_build_object('name','Test person','weekly_hours',42,'weekly_hours_source','contract','contract_confirmed',true),jsonb_build_object('active',true));
 perform pg_temp.assert_true(not exists(select 1 from jsonb_array_elements(public.schedule_issues(s.id)) i where i->>'code'='weekly'),'explicit confirmed 42-hour contract accepted');
 begin perform public.save_schedule(pg_temp.f('unit'),'2026-10-19',s.revision,0,rows,'Stale unit');raise exception 'TEST FAILED stale unit accepted';exception when sqlstate 'PT409' then null;end;
end $$;
reset role;
rollback;
select 'passed: inherited 42, preserved individual 40, confirmed 42, HTTP 409 version conflict' as verification;
